code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();

        while (b != 0) {
            long rest = a % b;
            a = b;
            b = rest;
        }
        System.out.println(a);
    }
}
